async function reconcile(env:Env) {
  const pending=(await env.DB.prepare("SELECT * FROM image_operations o WHERE (state IN ('PENDING','NEEDS_REPAIR','CLEANUP_PENDING') OR (kind='DELETE' AND state='COMMITTED') OR (kind='DELETE' AND state='COMPENSATED' AND cleanup_complete=0)) AND NOT EXISTS (SELECT 1 FROM listing_locks l WHERE l.listing_id=o.listing_id AND l.expires_at>unixepoch()) ORDER BY updated_at LIMIT 100").all<any>()).results;
  for(const op of pending){
    const lease=await lock(env.DB,op.listing_id); if(!lease) continue;
    try {
      await env.DB.prepare('UPDATE image_operations SET updated_at=? WHERE id=?').bind(now(),op.id).run();
      const row=await env.DB.prepare('SELECT id FROM listing_images WHERE object_key=?').bind(op.object_key).first();
      if(op.kind==='ADD'){
        if(row){let present=false;try{present=!!await env.IMAGES.head(op.object_key);}catch{}if(present)await bestEffortOperationState(env.DB,op.id,'COMMITTED');else await bestEffortOperationState(env.DB,op.id,'NEEDS_REPAIR');continue;}
        await compensateAdd(env.DB,env.IMAGES,op.id,op.object_key);
      }else if(op.kind==='DELETE'){
        const backup=op.backup_key?await env.IMAGES.get(op.backup_key):null;
        if(!row){
          const current=await ordered(env.DB,op.listing_id),positions=current.map(x=>x.position),dense=positions.every((position,i)=>position===i);
          if(!dense){const listing=await env.DB.prepare('SELECT owner_id FROM listings WHERE id=?').bind(op.listing_id).first<{owner_id:string}>();if(!listing||!await writeDenseOrder(env.DB,op.listing_id,listing.owner_id,lease,current)||!(await ordered(env.DB,op.listing_id)).every((x,i)=>x.position===i)){await bestEffortOperationState(env.DB,op.id,'NEEDS_REPAIR');continue;}}
          await env.IMAGES.delete(op.object_key);if(await env.IMAGES.head(op.object_key)){await bestEffortOperationState(env.DB,op.id,'NEEDS_REPAIR');continue;}if(op.backup_key){await env.IMAGES.delete(op.backup_key);if(await env.IMAGES.head(op.backup_key)){await bestEffortOperationState(env.DB,op.id,'CLEANUP_PENDING');continue;}}await bestEffortOperationState(env.DB,op.id,'CLEANED');continue;
        }
        if(row){if(!await env.IMAGES.head(op.object_key)){if(!backup){await bestEffortOperationState(env.DB,op.id,'NEEDS_REPAIR');continue;}await env.IMAGES.put(op.object_key,await backup.arrayBuffer(),{httpMetadata:{contentType:backup.httpMetadata?.contentType}});}if(!await env.IMAGES.head(op.object_key)){await bestEffortOperationState(env.DB,op.id,'NEEDS_REPAIR');continue;}if(op.backup_key)await cleanupDeleteBackup(env.DB,env.IMAGES,op.id,op.backup_key,'COMPENSATED');else await bestEffortOperationState(env.DB,op.id,'COMPENSATED');}
        else{await env.IMAGES.delete(op.object_key);if(op.backup_key)await env.IMAGES.delete(op.backup_key);await bestEffortOperationState(env.DB,op.id,'CLEANED');}
      }
    } catch(error) {
      console.error(JSON.stringify({event:'image_operation_recovery_deferred',operationId:op.id,kind:op.kind}));
    } finally { await unlock(env.DB,op.listing_id,lease); }
  }
}
async function reconcilePendingReorders(env:Env) {
  const pending=(await env.DB.prepare("SELECT o.* FROM image_reorder_operations o WHERE (o.state IN ('PENDING','NEEDS_REPAIR') AND o.retryable=1 AND unixepoch(o.updated_at)<=unixepoch()-300) OR (o.state='COMMITTED' AND o.retryable=1 AND EXISTS (SELECT 1 FROM idempotency_records r WHERE r.owner_id=o.owner_id AND r.scope=o.scope AND r.request_key=o.request_key AND r.request_fingerprint=o.request_fingerprint AND r.state IN ('PENDING','NEEDS_REPAIR'))) OR (o.state='NEEDS_REPAIR' AND o.retryable=0 AND NOT EXISTS (SELECT 1 FROM idempotency_records r WHERE r.owner_id=o.owner_id AND r.scope=o.scope AND r.request_key=o.request_key AND r.request_fingerprint=o.request_fingerprint AND r.state='NEEDS_REPAIR')) ORDER BY o.updated_at LIMIT 100").all<any>()).results;
  for(const candidate of pending){
    const lid=candidate.listing_id??candidate.scope.slice('IMAGE_REORDER:'.length).split(':')[0];
    if(!lid)continue;
    const lease=await lock(env.DB,lid);if(!lease)continue;
    try{
      const op=await env.DB.prepare('SELECT * FROM image_reorder_operations WHERE owner_id=? AND scope=? AND request_key=?').bind(candidate.owner_id,candidate.scope,candidate.request_key).first<any>();
      if(!op)continue;
      if(op.state==='NEEDS_REPAIR'&&op.retryable===0){if(!await repairRetiredReorderIdempotency(env.DB,op))console.error(JSON.stringify({event:'reorder_retirement_record_deferred',operationId:op.request_key}));continue;}
      if(op.retryable!==1||!['PENDING','NEEDS_REPAIR','COMMITTED'].includes(op.state))continue;
      if(op.state!=='COMMITTED'&&!await ensureReorderIdempotencyReservation(env.DB,op)){console.error(JSON.stringify({event:'reorder_reservation_pair_deferred',operationId:op.request_key}));continue;}
      if(op.state==='COMMITTED'){await confirmReorderIdempotency(env.DB,op.owner_id,op.scope,op.request_key,op.request_fingerprint,op.result_json);continue;}
      const prefix=`IMAGE_REORDER:${lid}:`,imageId=op.scope.startsWith(prefix)?op.scope.slice(prefix.length):'';
      let plan:any[];try{plan=JSON.parse(op.result_json);if(!Array.isArray(plan)||plan.some((row:any,index:number)=>typeof row?.id!=='string'||row.position!==index)||new Set(plan.map(row=>row.id)).size!==plan.length)throw Error('invalid reserved plan');}catch{plan=[];}
      const current=await ordered(env.DB,lid),ids=plan.map(row=>row.id),sameSet=!!imageId&&plan.length===current.length&&ids.includes(imageId)&&current.every(row=>ids.includes(row.id));
      if(!sameSet){const retirementAt=now();try{await env.DB.batch([env.DB.prepare("UPDATE image_reorder_operations SET state='NEEDS_REPAIR',retryable=0,updated_at=? WHERE owner_id=? AND scope=? AND request_key=? AND state IN ('PENDING','NEEDS_REPAIR') AND retryable=1").bind(retirementAt,op.owner_id,op.scope,op.request_key),env.DB.prepare("UPDATE idempotency_records SET state='NEEDS_REPAIR',updated_at=? WHERE owner_id=? AND scope=? AND request_key=? AND request_fingerprint=? AND state IN ('PENDING','NEEDS_REPAIR')").bind(retirementAt,op.owner_id,op.scope,op.request_key,op.request_fingerprint)]);}catch{}const retired=await env.DB.prepare('SELECT * FROM image_reorder_operations WHERE owner_id=? AND scope=? AND request_key=?').bind(op.owner_id,op.scope,op.request_key).first<any>();if(retired?.state!=='NEEDS_REPAIR'||retired.retryable!==0){console.error(JSON.stringify({event:'reorder_retirement_deferred',operationId:op.request_key}));continue;}if(!await repairRetiredReorderIdempotency(env.DB,retired))console.error(JSON.stringify({event:'reorder_retirement_record_deferred',operationId:op.request_key}));continue;}
      const plannedOrder=ids.map(id=>current.find((row:ImageRow)=>row.id===id)!);
      if(!await orderIs(env.DB,lid,ids)&&!await writeDenseOrder(env.DB,lid,op.owner_id,lease,plannedOrder)){await env.DB.prepare("UPDATE image_reorder_operations SET state='NEEDS_REPAIR',updated_at=? WHERE owner_id=? AND scope=? AND request_key=? AND state IN ('PENDING','NEEDS_REPAIR') AND retryable=1").bind(now(),op.owner_id,op.scope,op.request_key).run().catch(()=>{});continue;}
      if(!await orderIs(env.DB,lid,ids))continue;
      if(!await confirmReorderOperation(env.DB,op.owner_id,op.scope,op.request_key,op.request_fingerprint,op.result_json,lid,lease,ids))continue;
      await confirmReorderIdempotency(env.DB,op.owner_id,op.scope,op.request_key,op.request_fingerprint,op.result_json);
    }catch{console.error(JSON.stringify({event:'reorder_recovery_deferred',operationId:candidate.request_key}));}
    finally{await unlock(env.DB,lid,lease);}
  }
}
const worker = { fetch: app.fetch, scheduled: async (_controller: ScheduledController, env: Env) => { await reconcile(env);await reconcilePendingReorders(env); } };
export { app };
export default worker;
